"""Shared export pipeline for the CSV and JSON exporters."""

import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Yield id/name-only records, preserving input order.

    Missing keys and None values become "", every other value is
    stringified. Inputs are never mutated and one-shot iterables are
    consumed exactly once.
    """
    for row in rows:
        record = {}
        for key in _FIELDS:
            value = row.get(key)
            record[key] = "" if value is None else str(value)
        yield record


def _serialize_csv(rows):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    for record in _normalize(rows):
        writer.writerow([record[key] for key in _FIELDS])
    return buffer.getvalue()


def _serialize_json(rows):
    return json.dumps(
        list(_normalize(rows)),
        ensure_ascii=False,
        separators=(",", ":"),
    )


def export_rows(rows, format):
    """Serialize *rows* as ``csv`` or ``json``; raise ValueError otherwise."""
    if format == "csv":
        return _serialize_csv(rows)
    if format == "json":
        return _serialize_json(rows)
    raise ValueError("unsupported format")
